mapper.select:
SELECT * FROM brick_flow WHERE id IN

    #{id}

AND is_deleted = 0

SELECT f.* FROM brick_flow f
LEFT JOIN brick_flow_run r ON f.id = r.flow_id
WHERE f.is_deleted = 0

    AND f.name LIKE CONCAT('%', #{query.name}, '%')
    AND f.env = #{query.env}
    AND f.swagger_mapping_id = #{query.swaggerMappingId}
    AND f.app_config_id = #{query.appConfigId}


    AND r.status = #{executionStatus}

GROUP BY f.id
ORDER BY f.update_time DESC
LIMIT #{offset}, #{limit}

SELECT f.* FROM brick_flow f
INNER JOIN brick_flow_node n ON f.id = n.flow_id
WHERE f.is_deleted = 0 AND n.is_deleted = 0

    AND f.name LIKE CONCAT('%', #{query.name}, '%')
    AND f.env = #{query.env}

AND n.endpoint_id = #{endpointId}
GROUP BY f.id
ORDER BY f.update_time DESC
LIMIT #{offset}, #{limit}
